# Parse all JSON lines and content to find test input and demos
import os, json, re

session_file = "/home/USER/runs/paper/qwen-in-glm-hpl-u1-letter/frozen/held-out-3/play/users/u068/system/state/sessions/01a1bf32-3dfe-736b-afd2-38ff7935156c.jsonl"

with open(session_file, 'r') as f:
    lines = f.readlines()

# Find all content that contains grids
test_input = None
demo_pairs = []

for i, line in enumerate(lines):
    try:
        msg = json.loads(line)
        ctype = msg.get('type', '')
        if ctype == 'custom_message':
            content = msg.get('content', '')
            # Parse the customMessage format - could be a long text
            # Looking for "Test input" or "Demo pair"
            lines_in_msg = content.split('\n')
            for line_in in lines_in_msg:
                if 'Test input' in line_in:
                    # Find the test input grid
                    # It should be after "Test input (9x9):"
                    # Look for the formatted grid
                    all_content = content
                    grid_match = re.search(r'Test input \((\d+)x(\d+)\):\n((?:\d+\s*){8,}\n(?:\d+\s*){8,}\n(?:\d+\s*){8,}\n(?:\d+\s*){8,}\n(?:\d+\s*){8,}\n(?:\d+\s*){8,}\n(?:\d+\s*){8,}\n(?:\d+\s*){8,}\n(?:\d+\s*){8,}\n(?:\d+\s*){8,}\n)', all_content)[:5000]
                    print(f"Found Test input in line {i}")
                elif 'Demo pair' in line_in:
                    print(f"Found Demo pair line: {line_in[:200]}")
        elif ctype == 'message':
            content = msg.get('content', [{}])[0].get('text', '')
            print(f"Message type at line {i}: {content[:200] if content else 'empty'}...")
    except Exception as e:
        pass

# Let me just print all text content
print("\n=== All text content ===")
for i, line in enumerate(lines):
    try:
        msg = json.loads(line)
        if msg.get('type') == 'message':
            text = msg.get('content', [{}])[0].get('text', '')
            # Find if it has grid data
            if 'Test input' in text:
                print(f"Found Test input at line {i}")
            elif 'Demo pair' in text:
                print(f"Found Demo pair at line {i}")
    except:
        pass

